const mezclar = (a: Punto, b: Punto, p: number): Punto => [
  a[0] + (b[0] - a[0]) * p,
  a[1] + (b[1] - a[1]) * p,
];

const curva = (s: number, a: number, b: number) => {
  const p = interpolate(s, [a, b], [0, 1], clamp);
  return p * p * (3 - 2 * p);
};

const tramo = (s: number, a: number, b: number, fundido = 0.25) =>
  curva(s, a, a + fundido) * (1 - curva(s, b, b + fundido));

const local = (p: Punto, x: number, y: number, escala: number): Punto => [
  (p[0] - x) / escala,
  (p[1] - y) / escala,
];

const camara = (x: number, y: number, z: number) =>
