const Vapor: React.FC<{s: number; fase?: number; claro?: boolean}> = ({
  s,
  fase = 0,
  claro = false,
}) => (
  <g fill="none" stroke={claro ? '#fff9e9' : '#f5dfc4'} strokeWidth={5} strokeLinecap="round">
    {[0, 1, 2].map((i) => {
      const p = ((s * 0.24 + i / 3 + fase) % 1 + 1) % 1;
      const x = (i - 1) * 19;
      const balanceo = Math.sin(s * 1.25 + i + fase) * 11;
      return (
        <path
          key={i}
          d={`M${x} ${-98 - p * 95} C${x - 14 + balanceo} ${-127 - p * 95},${x + 17 + balanceo} ${-151 - p * 95},${x + balanceo} ${-182 - p * 95}`}
          opacity={Math.sin(p * Math.PI) * 0.47}
        />
      );
    })}
  </g>
);

