                cabeza={6 + curva(s, t.heri, t.gracias) * 5 - mirarSegunda * 7}
                mirada={mirarSegunda}
                pena={0.8 - curva(s, t.gracias, t.oportunidad) * 0.25}
                habla={ensayar * 0.65}
              />
            </g>

            <Taza s={s} x={tazaPrimera[0]} y={tazaPrimera[1]} inclinacion={Math.sin(trasladoPrimero * Math.PI) * -3} />
            <Taza s={s} x={875} y={1120} azul />

            <g opacity={mirarSegunda * 0.55}>
              <ellipse cx={875} cy={1126} rx={77 + Math.sin(s * 1.3) * 3} ry={14} fill="#ffe4b0" opacity={0.24} />
            </g>
          </g>
          <PrimerPlano s={s} opacidad={aperturaBucle} />
        </g>

        <g id="mesa-escuchar" display={toma === 1 ? undefined : 'none'}>
          <g transform={camara(540 + curva(s, t.dolio, t.valor) * 10, 960, zoomMesa)}>
            <Comedor s={s} />

            <g transform="translate(848 1673) scale(.99)">
              <Interlocutor
                s={s}
                dolor={curva(s, t.dolio, t.valor) * 0.72}
              />
            </g>

            <g transform={`translate(355 ${mujerMesaY}) scale(1.25)`}>
              <Mujer
                s={s}
                izquierda={manoMesaI}
                derecha={manoMesaD}
                cabeza={
                  1
                  + reconocer * 6
                  + curva(s, t.dolio, t.valor) * 4
                  + Math.sin(s * 1.35) * abrirEscucha * 0.9
                }
                mirada={1}
                pena={0.58}
                habla={reconocer * 0.65}
                sentada={sentarse > 0.5}
              />
            </g>

            <MesaComedor />

            <Taza s={s} x={804} y={1348} escala={0.98} />
            <Taza
              s={s}
              x={tazaSegunda[0]}
              y={tazaSegunda[1]}
              azul
              inclinacion={-Math.sin(llevarSegunda * Math.PI) * 3}
            />
            <Telefono
              x={telefonoP[0]}
              y={telefonoP[1]}
              giro={-24 * (1 - retirarTelefono)}
            />

            <g transform={`translate(355 ${mujerMesaY}) scale(1.25)`}>
              <g transform={`translate(${manoMesaI[0]} ${manoMesaI[1] + 7})`}>
                <circle r={23} fill="url(#piel-mujer)" />
              </g>
              <g transform={`translate(${manoMesaD[0]} ${manoMesaD[1] + 7})`}>
                <circle r={23} fill="url(#piel-mujer)" />
              </g>
            </g>

            <path
              d={`M677 1323Q${680 + Math.sin(s * 0.8) * 3} 1309 699 1318L712 1340L680 1348Z`}
              fill="#eee0b9"
            />
            <path d="M686 1321L697 1339" stroke="#cfbd94" strokeWidth={2} />
          </g>
        </g>

        <g id="rincon-oracion" display={toma === 2 ? undefined : 'none'}>
          <g transform={camara(540, 960 + tramo(s, t.efesios, t.manos, 0.5) * 35, zoomOracion)}>
            <Rincon s={s} />

            <g transform="translate(530 1825) scale(1.29)">
              <Mujer
                s={s}
                izquierda={manoOracionI}
                derecha={manoOracionD}
                cabeza={8 - manosAbiertas * 5 + Math.sin(s * 0.8) * 0.6}
                mirada={0}
                pena={0.32}
                cerrados={s < t.ensename || s > t.manos}
                arrodillada
              />
            </g>

            <g
              transform={`translate(530 ${1371 + devolverLibro * 53}) scale(1.02)`}
              opacity={curva(s, t.ensename, t.voz)}
            >
              <Libro apertura={abrirLibro} />
            </g>

            <g transform="translate(530 1825) scale(1.29)">
              <circle cx={manoOracionI[0]} cy={manoOracionI[1] + 7} r={23} fill="url(#piel-mujer)" />
              <circle cx={manoOracionD[0]} cy={manoOracionD[1] + 7} r={23} fill="url(#piel-mujer)" />
              <path
                d={`M${manoOracionI[0] - 10} ${manoOracionI[1] + 3}Q${manoOracionI[0]} ${manoOracionI[1] - 4},${manoOracionI[0] + 10} ${manoOracionI[1] + 3}`}
                stroke="#f1c59a"
                strokeWidth={3}
                fill="none"
                opacity={manosAbiertas * 0.7}
              />
              <path
                d={`M${manoOracionD[0] - 10} ${manoOracionD[1] + 3}Q${manoOracionD[0]} ${manoOracionD[1] - 4},${manoOracionD[0] + 10} ${manoOracionD[1] + 3}`}
                stroke="#f1c59a"
                strokeWidth={3}
                fill="none"
                opacity={manosAbiertas * 0.7}
              />
            </g>
          </g>
        </g>

        <g id="dos-cafes-disculpa" display={toma === 3 ? undefined : 'none'}>
          <g transform={camara(540, 960, 1.015 + curva(s, t.contigo, t.hablar) * 0.025)}>
            <Cocina s={s} />

            <g transform="translate(600 1740) scale(1.28)">
              <Mujer
                s={s}
                izquierda={manoFinalI}
                derecha={manoFinalD}
                cabeza={3 + cerrarOracion * 5}
                mirada={-0.5}
                pena={0.16}
                cerrados={cerrarOracion > 0.5}
              />
            </g>

            <g transform={`translate(${bandeja[0]} ${bandeja[1]})`}>
              <ellipse cx={0} cy={12} rx={181} ry={25} fill="#60412d" opacity={0.18} />
              <path d="M-181-10Q0-49 181-10L178 16Q0 46-178 16Z" fill="#976d48" />
              <ellipse cy={-10} rx={181} ry={29} fill="#c99d69" />
              <path d="M-167-8Q0 18 167-8" stroke="#e0bc87" strokeWidth={3} fill="none" />
              <Taza s={s} x={-83} y={-12} escala={0.93} />
              <Taza s={s} x={83} y={-12} escala={0.93} azul />
            </g>

            <g transform="translate(600 1740) scale(1.28)">
              <circle cx={manoFinalI[0]} cy={manoFinalI[1] + 7} r={23} fill="url(#piel-mujer)" />
              <circle cx={manoFinalD[0]} cy={manoFinalD[1] + 7} r={23} fill="url(#piel-mujer)" />
            </g>
          </g>

          <PrimerPlano s={s} opacidad={cierreBucle} />
        </g>

        <rect width={1080} height={1920} fill="url(#vineta)" pointerEvents="none" />
      </svg>
    </AbsoluteFill>
  );
};
